/* =========================
   Utilities
   ========================= */
function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  }[c]));
}

function escapeAttr(s) {
  return escapeHtml(s);
}

function escapeJs(s) {
  return String(s ?? "").replaceAll("\\", "\\\\").replaceAll("'", "\\'");
}

function withCacheBuster(url) {
  const sep = url.includes("?") ? "&" : "?";
  return url + sep + "v=" + Date.now();
}

async function fetchJson(url, label) {
  const res = await fetch(withCacheBuster(url));
  if (!res.ok) throw new Error(`Failed to load ${label} (${res.status})`);
  return res.json();
}

/* =========================
   Data loader
   ========================= */
async function loadAllData() {
  const researcherUrl =
    "https://sleepy-meh-alt-1.github.io/Archealogy-research-tracker/data/researcher.json";
  const artefactUrl =
    "https://sleepy-meh-alt-1.github.io/Archealogy-research-tracker/data/artefacts.json";
  const materialUrl =
    "https://sleepy-meh-alt-1.github.io/Archealogy-research-tracker/data/materials.json";

  const [researcherJson, artefactJson, materialJson] = await Promise.all([
    fetchJson(researcherUrl, "researcher.json"),
    fetchJson(artefactUrl, "artefacts.json"),
    fetchJson(materialUrl, "materials.json")
  ]);

  RESEARCHERS = researcherJson.researchers || [];
  artefactData = artefactJson;
  materialData = materialJson.materials;

  lastGeUpdate = materialJson.last_ge_update  
  materialBank = {};
  for (const m of materialData) {
    materialBank[m.name.toLowerCase()] = {
      name: m.name,
      owned: 0,
      needed: 0,
      missing: 0,
      surplus: 0
    };
  }

  console.log("Researchers loaded:", RESEARCHERS.length);
  console.log("Artefacts loaded:", Object.keys(artefactData.artefacts || {}).length);
  console.log("Materials loaded:", materialData.length);
  console.log()
  console.log("Material bank initialized:", Object.keys(materialBank).length);
}

