function getFilteredHistory(siteSelId, durSelId) {
  const history = loadHistory();
  const siteFilter = document.getElementById(siteSelId)?.value || "";
  const durationFilter = document.getElementById(durSelId)?.value || "";

  let view = [...history];

  if (siteFilter) view = view.filter((rec) => rec.research?.siteId === siteFilter);
  if (durationFilter) view = view.filter((rec) => String(rec.research?.hours) === String(durationFilter));

  return view;
}

