async function initApp() {
  try {
    await loadAllData();
  } catch (err) {
    console.error("Data loading failed:", err);
    showToast("Data loading failed (check console).");
    return;
  }

  const avg = document.getElementById("averages");
  if (avg) avg.style.display = "none";

  // Timer
  initResearchTimerLoop();
  document.getElementById("startTimerBtn")?.addEventListener("click", () => startResearchCooldown(Date.now()));

  // Core buttons
  document.getElementById("scanBtn")?.addEventListener("click", scan);
  document.getElementById("scanBankBtn")?.addEventListener("click", scanBank);
  document.getElementById("scanMaterialBankBtn")?.addEventListener("click", scanMaterialBank);

  // History modal
  document.getElementById("historyBtn")?.addEventListener("click", openHistory);
  document.getElementById("closeHistoryBtn")?.addEventListener("click", closeHistory);

  const historyModal = document.getElementById("historyModal");
  historyModal?.addEventListener("click", (e) => {
    if (e.target === historyModal) closeHistory();
  });
  historyModal?.querySelector(".modalContent")?.addEventListener("click", (e) => e.stopPropagation());

  // History delete confirm
  document.getElementById("historyList")?.addEventListener("click", (e) => {
    const btn = e.target.closest("button[data-del]");
    if (!btn) return;
    e.stopPropagation();

    const state = btn.getAttribute("data-state") || "idle";
    const ts = Number(btn.getAttribute("data-del"));

    if (state === "idle") {
      btn.textContent = "Confirm";
      btn.setAttribute("data-state", "confirm");
      btn.classList.add("danger");

      setTimeout(() => {
        if (btn.getAttribute("data-state") === "confirm") {
          btn.textContent = "Delete";
          btn.setAttribute("data-state", "idle");
          btn.classList.remove("danger");
          btn.classList.add("small");
        }
      }, 3500);

      return;
    }

    deleteRecordByTimestamp(ts);
  });

  // Stats modal
  document.getElementById("statsBtn")?.addEventListener("click", openStats);
  document.getElementById("closeStatsBtn")?.addEventListener("click", closeStats);
  document.getElementById("statsModal")?.addEventListener("click", (e) => {
    if (e.target === document.getElementById("statsModal")) closeStats();
  });

  // Missing modal
  document.getElementById("missingBtn")?.addEventListener("click", () => {
    renderMissingModal();
    openMissingModal();
  });
  document.getElementById("closeMissingBtn")?.addEventListener("click", closeMissingModal);
  document.getElementById("missingModal")?.addEventListener("click", (e) => {
    if (e.target === document.getElementById("missingModal")) closeMissingModal();
  });

  // Team UI
  const addBtn = document.getElementById("addResearcherBtn");
  const clearBtn = document.getElementById("clearTeamBtn");
  const select = document.getElementById("researcherSelect");

  addBtn?.addEventListener("click", () => addToTeam(select?.value));
  clearBtn?.addEventListener("click", clearTeam);
  select?.addEventListener("dblclick", () => addToTeam(select.value));

  // Initial renders
  refreshTeamUI();
  refreshStats();
  initResearchPlannerUI();
  initHistoryFilters();
  initStatsFilters();
  fetchPrices()
}

window.addEventListener("DOMContentLoaded", initApp);